import React from "react";
import styles from "./Home.module.css";
function Home(){
    return(
        <div className={styles.HomeContainer}>
            <h2 className={styles.HomeContainer_h2}>Hello,it's Me</h2>
            <h3 className={styles.HomeContainer_h3}>Name</h3> {/* get it from database */}
            <h4 className={styles.HomeContainer_h4}>And I'm a ROLE</h4>
            <img src="" className="{styles.img}"></img>
            
        </div>
    )
}
export default Home;
